 11	namespace Slic3r::GUI::JusPrin::Agent {
 12	
 13	namespace {
 14	
 15	constexpr const char* kSection = "jusprin_agent";
 16	
 17	std::string api_key_item_for(const std::string& provider) { return provider + "_api_key"; }
 18	
 19	ProviderListeners logging_listeners()
 20	{
 21	    ProviderListeners listeners;
 22	    // Refused tool calls never reach a card or the activity list; the log is
 23	    // where a wrong call can be read afterwards.
 24	    listeners.refusal = [](const std::string& tool, const std::string& arguments, const std::string& code) {
 25	        BOOST_LOG_TRIVIAL(warning) << "Agent tool call refused (" << code << "): " << tool << " " << arguments.substr(0, 1024);
 26	    };
 27	    return listeners;
 28	}
 29	
 30	bool configured_true(const AppConfig* config, const char* key)
 31	{
 32	    if (config == nullptr)
 33	        return false;
 34	    const std::string value = config->get(kSection, key);
 35	    return value == "true" || value == "1";
 36	}
 37	
 38	} // namespace
 39	
 40	std::string load_provider_api_key(const AppConfig* config, const std::string& provider)
 41	{
 42	    return config == nullptr ? std::string() : config->get(kSection, api_key_item_for(provider));
 43	}
 44	
 45	AgentRuntime load_agent_runtime(AppConfig* config)
 46	{
 47	    AgentSettings settings;
 48	    settings.enabled       = configured_true(config, "enabled");
 49	    settings.cloud_consent = configured_true(config, "cloud_consent");
 50	    if (config != nullptr) {
 51	        settings.provider = config->get(kSection, "provider");
 52	        settings.model    = config->get(kSection, "model");
 53	    }
 54	    settings.api_key = load_provider_api_key(config, settings.provider.empty() ? "openai" : settings.provider);
 55	    AgentRuntime runtime = resolve_agent_runtime(settings, agent_endpoint_override(), &make_openai_http_transport, logging_listeners());
 56	    runtime.setup        = make_agent_setup(config);
 57	    return runtime;
 58	}
 59	
 60	AgentSetupServicePtr make_agent_setup(AppConfig* config)
 61	{
 62	    // Committing is the only part of setup that touches the machine, so it
 63	    // lives here rather than in the GUI-free probe. Reaching this point means
 64	    // the user read what the dock says about the provider billing them and
 65	    // about the key staying on this machine, and chose to continue: that is
 66	    // the cloud consent load_agent_runtime() requires on the next launch.
 67	    auto commit = [config](const SetupCredentials& credentials) {
 68	        if (config == nullptr || credentials.provider.empty() || credentials.api_key.empty())
 69	            return false;
 70	        config->set(kSection, api_key_item_for(credentials.provider), credentials.api_key);
 71	        config->set(kSection, "provider", credentials.provider);
 72	        config->set(kSection, "enabled", "true");
 73	        config->set(kSection, "cloud_consent", "true");
 74	        if (!credentials.model.empty())
 75	            config->set(kSection, "model", credentials.model);
 76	        // Written now, not at the next routine save, so a crash after setup
 77	        // does not lose a key the user was just told is stored.
 78	        config->save();
 79	        return true;
 80	    };
 81	    return std::make_shared<ProviderKeySetup>(&make_openai_http_transport, std::move(commit), agent_endpoint_override());
 82	}
