 31	// Shared provider credential lookup for bounded, non-conversational features
 32	// such as printer recognition. The key is an AppConfig item, "<provider>_api_key"
 33	// in the Agent section, rather than an OS credential-store entry: macOS asks
 34	// for the login password whenever a differently signed build reads a Keychain
 35	// entry, which every unsigned rebuild is.
 36	std::string load_provider_api_key(const AppConfig* config, const std::string& provider);
 37	
 38	// The setup service the Agent dock drives: it verifies a candidate key
 39	// against the live provider and, on success, stores it and records the
 40	// non-secret choices load_agent_runtime() reads on the next launch.
 41	AgentSetupServicePtr make_agent_setup(AppConfig* config);
 42	
 43	// The docked Agent's per-chat models: every provider with a stored key, the
 44	// default provider setup recorded, agents built from those keys, and each
 45	// provider's model list fetched from the provider. `post` runs a callback on
 46	// the GUI thread; the lists arrive through it.
 47	std::shared_ptr<IChatModelSource> make_chat_model_source(AppConfig* config,
 48	                                                         std::function<void(std::function<void()>)> post);
