  1	// The Agent setup surface. It replaces the dock's body in place rather than
  2	// opening a dialog: setting up an Agent changes nothing about the print, so
  3	// it stays inside the same panel the offer was made in, and every screen can
  4	// be backed out of without leaving anything behind.
  5	
  6	import { useEffect, useRef, useState } from 'react';
  7	import { SetupStatusPayload } from '../bridge/protocol';
  8	
  9	// The page and the host ship in the same build, so this list and the host's
 10	// setup_provider_supported() are two views of the same fact. The host still
 11	// validates: an unsupported provider comes back as a visible setup error
 12	// rather than a request that never answers.
 13	interface ProviderOption {
 14	  id: string;
 15	  label: string;
 16	  placeholder: string;
 17	  available: boolean;
 18	}
 19	
 20	export const PROVIDERS: ProviderOption[] = [
 21	  { id: 'anthropic', label: 'Anthropic', placeholder: 'sk-ant-…', available: true },
 22	  { id: 'openai', label: 'OpenAI', placeholder: 'sk-…', available: true },
 23	  { id: 'openrouter', label: 'OpenRouter', placeholder: 'sk-or-…', available: true },
 24	  { id: 'other', label: 'Other…', placeholder: '', available: false },
 25	];
 26	
 27	// OpenAI stays the tab a new setup opens on; the others are a click away.
 28	export const DEFAULT_PROVIDER = 'openai';
 29	
 30	export function providerLabel(id: string | undefined): string {
 31	  return PROVIDERS.find((provider) => provider.id === id)?.label ?? 'your provider';
 32	}
 33	
 34	function seconds(elapsedMs: number): string {
 35	  return `${(elapsedMs / 1000).toFixed(1)} s`;
 36	}
 37	
 38	export interface SetupChooserProps {
 39	  onUseApiKey: () => void;
 40	  onConnectTool: () => void;
 41	  onDismiss: () => void;
 42	}
 43	
 44	export function SetupScreenTitle({ label, onBack }: { label: string; onBack: () => void }) {
 45	  return (
 46	    <div className="setup-card-head">
 47	      <button type="button" className="back" onClick={onBack} aria-label="Back to setup options">
 48	        <span className="chevron" aria-hidden="true" />
 49	      </button>
 50	      <h1>{label}</h1>
 51	    </div>
 52	  );
 53	}
 54	
 55	export function SetupChooser({ onUseApiKey, onConnectTool, onDismiss }: SetupChooserProps) {
 56	  const laterTitle = 'This way of connecting an Agent arrives in a later JusPrin release';
 57	  return (
 58	    <div className="pane-state setup" data-testid="setup-chooser">
 59	      <div className="setup-card">
 60	        <div className="setup-card-head">
 61	          <h1>Set up the agent</h1>
 62	          <button className="icon" onClick={onDismiss} aria-label="Close setup">
 63	            <span className="jp-icon jp-icon-close" aria-hidden="true" />
 64	          </button>
 65	        </div>
 66	        <p>
 67	          It reads what you ask for and writes the settings underneath. It needs somewhere to think.
 68	        </p>
 69	        <button className="primary wide" disabled title={laterTitle}>
 70	          Continue with JusPrin
 71	        </button>
 72	        <p className="footnote">Free account · sign in with your browser · nothing to install</p>
 73	
 74	        <p className="setup-eyebrow">If you know what these are</p>
 75	        <button className="setup-row" onClick={onUseApiKey} data-testid="setup-row-api-key">
 76	          <span>Use your own API key</span>
 77	          <span className="jp-icon jp-icon-chevron-right" aria-hidden="true" />
 78	        </button>
 79	        <button className="setup-row" onClick={onConnectTool} data-testid="setup-row-connect-tool">
 80	          <span>Connect an AI tool you already use</span>
 81	          <span className="jp-icon jp-icon-chevron-right" aria-hidden="true" />
 82	        </button>
 83	      </div>
 84	      <p className="footnote">
 85	        You can change this later. Nothing here is saved in the project.
 86	      </p>
 87	    </div>
 88	  );
 89	}
 90	
 91	export interface SetupApiKeyProps {
 92	  setup: SetupStatusPayload;
 93	  onCheck: (provider: string, apiKey: string) => void;
 94	  onCancel: () => void;
 95	  onBack: () => void;
 96	}
 97	
 98	export function SetupApiKey({ setup, onCheck, onCancel, onBack }: SetupApiKeyProps) {
 99	  const [provider, setProvider] = useState(DEFAULT_PROVIDER);
100	  const [key, setKey] = useState('');
101	  const [pasteAvailable, setPasteAvailable] = useState(false);
102	  const input = useRef<HTMLInputElement>(null);
103	
104	  // Clipboard reads are not granted in every embedded web view; the paste
105	  // shortcut appears only where it will actually work. Typing and the
106	  // platform's own paste always do.
107	  useEffect(() => {
108	    setPasteAvailable(
109	      typeof navigator !== 'undefined' && !!navigator.clipboard && typeof navigator.clipboard.readText === 'function',
110	    );
111	  }, []);
112	
113	  const checking = setup.phase === 'checking';
114	  const option = PROVIDERS.find((candidate) => candidate.id === provider)!;
115	
116	  const paste = () => {
117	    navigator.clipboard
118	      .readText()
119	      .then((text) => {
120	        setKey(text.trim());
121	        input.current?.focus();
122	      })
123	      .catch(() => {
124	        // Refused at the OS or view level: leave the field alone and let the
125	        // user paste the way they always could.
126	        input.current?.focus();
127	      });
128	  };
129	
130	  const submit = () => {
131	    if (!key.trim() || checking) return;
132	    onCheck(provider, key.trim());
133	  };
134	
135	  return (
136	    <div className="pane-state setup" data-testid="setup-api-key">
137	      <div className="setup-card">
138	        <SetupScreenTitle label="Your own API key" onBack={onBack} />
139	        <p>Billed by your provider, not JusPrin. Stored on this machine only.</p>
140	
141	        <div className="setup-tabs" role="tablist" aria-label="Provider">
142	          {PROVIDERS.map((candidate) => (
143	            <button
144	              key={candidate.id}
145	              role="tab"
146	              aria-selected={candidate.id === provider}
147	              className={candidate.id === provider ? 'setup-tab selected' : 'setup-tab'}
148	              disabled={!candidate.available}
149	              title={candidate.available ? undefined : `${candidate.label} support arrives in a later JusPrin release`}
150	              onClick={() => setProvider(candidate.id)}
151	            >
152	              {candidate.label}
153	            </button>
154	          ))}
155	        </div>
156	
157	        <div className="setup-key">
158	          <input
159	            ref={input}
160	            type="password"
161	            className="setup-key-input"
162	            aria-label={`${option.label} API key`}
163	            placeholder={option.placeholder}
164	            value={key}
165	            disabled={checking}
166	            onChange={(event) => setKey(event.target.value)}
167	            onKeyDown={(event) => {
168	              if (event.key === 'Enter') submit();
169	            }}
170	          />
171	          {pasteAvailable && (
172	            <button className="link" onClick={paste} disabled={checking}>
173	              paste
174	            </button>
175	          )}
176	        </div>
177	
178	        <div className="setup-actions">
179	          <button className="primary" onClick={submit} disabled={checking || key.trim().length === 0}>
180	            Check key
181	          </button>
182	          {checking && (
183	            <button className="link" onClick={onCancel}>
184	              Cancel
185	            </button>
186	          )}
187	          <SetupResult setup={setup} />
188	        </div>
189	
190	        <p className="footnote">
191	          Each chat starts on this provider’s recommended model. You can switch the model, or the provider, in any chat.
192	        </p>
193	      </div>
194	    </div>
195	  );
196	}
197	
198	function SetupResult({ setup }: { setup: SetupStatusPayload }) {
199	  if (setup.phase === 'checking') return <span className="setup-result">Checking…</span>;
200	  if (setup.phase === 'verified')
201	    return (
202	      <span className="setup-result ok" data-testid="setup-verified">
203	        <span className="jp-icon jp-icon-check" aria-hidden="true" /> replied in {seconds(setup.elapsedMs ?? 0)}
204	      </span>
205	    );
206	  if (setup.phase === 'error')
207	    return (
208	      <span className="setup-result error" role="alert" data-testid="setup-error">
209	        {setup.error?.message ?? 'The key could not be checked.'}
210	      </span>
211	    );
212	  return null;
213	}
214	
215	export interface ConnectedBannerProps {
216	  provider: string;
217	  warning?: string;
218	  onDismiss: () => void;
219	}
220	
221	// Shown once, immediately after setup succeeds. The durable record of how the
222	// Agent is connected lives in Preferences; this is only the confirmation that
223	// the thing the user just did worked.
224	export function ConnectedBanner({ provider, warning, onDismiss }: ConnectedBannerProps) {
225	  return (
226	    <div className={warning ? 'setup-banner warning' : 'setup-banner'} data-testid="setup-connected">
227	      <span className="setup-banner-text">
228	        <span className="jp-icon jp-icon-check" aria-hidden="true" />
229	        <span>Connected · your own {providerLabel(provider)} key{warning ? ` — ${warning}` : ''}</span>
230	      </span>
231	      <button className="icon" onClick={onDismiss} aria-label="Dismiss">
232	        <span className="jp-icon jp-icon-close" aria-hidden="true" />
233	      </button>
234	    </div>
235	  );
236	}

