  provider?: string;
  elapsedMs?: number;
  error?: AgentErrorInfo;
  warning?: string;
}

export interface McpToolInfo {
  id: string;
  name: string;
  subtitle?: string;
  detected: boolean;
  cli: boolean;
  text: string;
  configPath?: string;
}

export interface McpCatalogPayload {
