.pane-state.setup {
  justify-content: flex-start;
  align-self: stretch;
  min-height: 0;
  overflow-y: auto;
}

.setup-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  width: 100%;
  padding: 16px;
  border-radius: var(--radius-large);
  background: var(--surface-selected);
}

.setup-card-head {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
}

.setup-card-head h1 {
  flex: 1;
  font: var(--font-section);
  margin: 0;
}

.setup-card p {
  margin: 0;
  color: var(--text-secondary);
}

button.primary.wide {
  width: 100%;
}

button.wide {
  width: 100%;
}

.setup-eyebrow {
  margin: 8px 0 0;
  font: var(--font-metadata);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.setup-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 8px 0;
  border: none;
  border-top: 1px solid var(--border-subtle);
  border-radius: 0;
  background: transparent;
  color: var(--text-primary);
  text-align: left;
  cursor: pointer;
}

.setup-row:hover:enabled,
.setup-row:active:enabled {
  background: transparent;
  border: none;
  border-top: 1px solid var(--border-subtle);
}

.setup-row:disabled {
  color: var(--action-disabled-text);
  cursor: default;
}

/* The provider switch is the design system's Segmented Control: a subtle
   track holding equal segments, the chosen one filled with action/primary. */
.setup-tabs {
  display: flex;
  box-sizing: border-box;
  width: 100%;
  height: var(--segmented-height);
  padding: var(--segmented-padding);
  border: var(--segmented-border-width) solid var(--border-subtle);
  border-radius: var(--segmented-radius);
  background: var(--surface-subtle);
}

.setup-tab {
  flex: 1;
  height: var(--segmented-segment-height);
  padding: var(--segmented-segment-padding-y) var(--segmented-segment-padding-x);
  border: none;
  border-radius: var(--segmented-radius);
  background: transparent;
  font: var(--font-label);
  color: var(--text-primary);
  cursor: pointer;
}

.setup-tab:hover:enabled,
.setup-tab:active:enabled {
  border: none;
}

.setup-tab.selected {
  background: var(--action-primary);
  color: var(--action-primary-text);
}

.setup-tab.selected:hover:enabled {
  background: var(--action-primary);
}

.setup-tab:disabled {
  color: var(--action-disabled-text);
  cursor: default;
}

.setup-key {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
}

/* Shares the compact radius and height of the primary button beside it so
   the key row reads as one control. A key is code. */
.setup-key-input {
  flex: 1;
  min-width: 0;
  padding: var(--button-secondary-padding);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-medium);
  background: var(--surface-canvas);
  color: var(--text-primary);
  font: var(--font-code);
}

.setup-key-input:focus {
  outline: 2px solid var(--border-focus);
  outline-offset: -1px;
}

.setup-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  width: 100%;
}

.setup-result {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font: var(--font-label);
  color: var(--text-secondary);
}

.setup-result.ok {
  color: var(--status-success);
}

.setup-result.error {
  color: var(--status-danger);
}

/* One-time confirmation that the setup the user just completed worked. */
.setup-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
/* Every color, radius, and type metric below resolves through a custom
   property that tokens.ts writes from resources/jusprin/ui/design-tokens.json:
   --<group>-<name> for colors, --radius-<name> for radii, --font-<role> for
   the `font` shorthand of each type role and --font-code for code. Padding,
   margin, and gap stay literal but must sit on the spacing scale. styles.test.ts
   fails the build on any literal outside those rules. */

/* The product font ships with OrcaSlicer, but it is registered as a private
   font of the native process and WKWebView renders in a separate process
   that cannot see it. A Latin subset is embedded so the Agent page uses the
   same face as the native shell; CJK text falls through to the system font. */
@font-face {
  font-family: 'HarmonyOS Sans SC';
  font-weight: 400;
  font-style: normal;
  src: url('../../WebShared/fonts/HarmonyOS_Sans_SC_Regular_latin.woff') format('woff');
}
@font-face {
  font-family: 'HarmonyOS Sans SC';
  font-weight: 700;
  font-style: normal;
  src: url('../../WebShared/fonts/HarmonyOS_Sans_SC_Bold_latin.woff') format('woff');
}

* {
  box-sizing: border-box;
}

html,
body,
  padding-left: 8px;
  border-left: 3px solid var(--border-strong);
  color: var(--text-secondary);
}

.markdown-content code,
.markdown-content pre {
  font: var(--font-code);
}

.markdown-content code {
  padding: 0 4px;
  border-radius: var(--radius-small);
  background: var(--surface-subtle);
}

.markdown-content pre {
  max-width: 100%;
  padding: 8px;
  border-radius: var(--radius-small);
  background: var(--surface-subtle);
  overflow-x: auto;
  white-space: pre;
}

.markdown-content pre code {

