        open(os.path.join(HERE, 'provider.log'), 'a').write(f'{self.command} {self.path} hang={os.path.exists(os.path.join(HERE,"hang"))}\n')
        while os.path.exists(os.path.join(HERE, 'hang')):
            time.sleep(0.5)
